// Author: MiYu. Verify visible native placement instances, shared poses, animation and independent GPU view lifetimes.
use mengine_assets::{AssetByteCache,WarcraftArchives,WarcraftMapSession,WarcraftMapDefinitions,WarcraftDefinitionCache,WarcraftResourceCache,WarcraftPlacedWorld};
use mengine_editor_host::{MountedWarcraftPlacedWorld,WarcraftWorldRenderLimits};
use mengine_rhi::{Renderer,RenderObject,RenderFrame,RenderTarget,FrameCamera,FrameLighting,ClearColor,look_at,perspective};
use glam::Vec3;
use std::{path::PathBuf,sync::Arc};
use winit::dpi::PhysicalSize;
fn draw(renderer:&mut Renderer,objects:&[RenderObject],camera:FrameCamera,target:&mengine_rhi::OffscreenRenderTarget)->anyhow::Result<Vec<u8>> {let mut lighting=FrameLighting::default(); lighting.environment.tone_mapping=false; lighting.environment.background_enabled=false; renderer.submit_frame_to(&RenderFrame {clear:ClearColor {r:0.03,g:0.02,b:0.04,a:1.},camera,objects,lighting:&lighting,ui:None,scene_views:&[]},RenderTarget::Offscreen(target))?; Ok(renderer.read_offscreen_rgba8(target)?)}
fn changed(a:&[u8],b:&[u8])->usize {a.chunks_exact(4).zip(b.chunks_exact(4)).filter(|(a,b)|a!=b).count()}
fn main()->anyhow::Result<()> {
    let mut args=std::env::args_os().skip(1); let game=PathBuf::from(args.next().ok_or_else(||anyhow::anyhow!("Provide game directory and Amazonia map"))?); let map=PathBuf::from(args.next().ok_or_else(||anyhow::anyhow!("Provide map"))?); let output=args.next().map(PathBuf::from).unwrap_or_else(||PathBuf::from("tmp/docs-artifacts/warcraft-archives/placed-gpu"));
    let bytes=Arc::new(AssetByteCache::default()); let archives=WarcraftArchives::open(&game,0,bytes.clone(),32*1024*1024)?; let session=WarcraftMapSession::open(&archives,&map,Default::default(),&Default::default())?; let data=Arc::new(session.load_world_data(Default::default(),&Default::default())?); let defs=Arc::new(WarcraftMapDefinitions::load(&session,data,&WarcraftDefinitionCache::default(),Default::default(),&Default::default())?); let resources=WarcraftResourceCache::default(); let world=WarcraftPlacedWorld::load(&session,defs,&resources,Default::default(),[1,1],&Default::default())?;
    let selected=world.nodes.iter().enumerate().filter(|(_,n)|n.id==Some(*b"nshe") && n.active).map(|(i,_)|i).take(2).collect::<Vec<_>>(); anyhow::ensure!(selected.len()==2,"Map must contain two original sheep placements"); let focus=Vec3::from_array(world.nodes[selected[0]].transform.unwrap().position)+Vec3::new(0.,0.25,0.); let eye=focus+Vec3::new(1.8,1.4,2.2); let look=(focus-eye).normalize();
    let mounted=MountedWarcraftPlacedWorld::load(&session,world.clone(),&resources,128*1024*1024,&Default::default())?; let before=bytes.stats(); drop(session); let after=bytes.stats(); anyhow::ensure!(after.resident_bytes<before.resident_bytes,"Map cache survived source-session close");
    let size=PhysicalSize::new(640,480); let mut first=Renderer::new_shared_headless(size)?; let mut second=Renderer::new_shared_headless(size)?; let a=first.create_offscreen_target(size); let b=second.create_offscreen_target(size); let camera=FrameCamera {view:look_at(eye,focus,Vec3::Y),proj:perspective(35.,640./480.,0.05,100.),position:eye}; let blank=draw(&mut first,&[],camera,&a)?;
    anyhow::ensure!(mounted.bind_nodes(&mut first,&selected,look,Vec3::Y,0,WarcraftWorldRenderLimits {max_draws:0,..Default::default()}).is_err(),"Draw limit did not reject"); anyhow::ensure!(first.material_texture_stats().color==0,"Rejected plan uploaded textures");
    let mut view=mounted.bind_nodes(&mut first,&selected,look,Vec3::Y,0,Default::default())?; anyhow::ensure!(view.pose_groups()<selected.len(),"Matching source placements did not share a pose"); anyhow::ensure!(view.parent_nodes().iter().all(|i|selected.contains(i)),"Native render parts lost their source placement parent"); let initial=draw(&mut first,view.objects(),camera,&a)?; anyhow::ensure!(changed(&blank,&initial)>100,"Native source placement did not contribute GPU pixels");
    view.update(&mut first,500,look,Vec3::Y)?; let animated=draw(&mut first,view.objects(),camera,&a)?; anyhow::ensure!(changed(&initial,&animated)>10,"Native placement animation did not change pixels"); view.update(&mut first,0,look,Vec3::Y)?;
    let mut other=mounted.bind_nodes(&mut second,&selected,look,Vec3::Y,0,Default::default())?; anyhow::ensure!(draw(&mut second,other.objects(),camera,&b)?==initial,"Second placement view differs"); anyhow::ensure!(view.release(&mut second).is_err(),"Wrong renderer released a placement view"); let groups=view.pose_groups(); let object_count=view.objects().len(); let old=view.objects().to_vec(); view.release(&mut first)?; anyhow::ensure!(draw(&mut first,&old,camera,&a)?==blank,"Released placement meshes still draw"); other.update(&mut second,500,look,Vec3::Y)?; anyhow::ensure!(draw(&mut second,other.objects(),camera,&b)?==animated,"Released first view damaged second view update"); let old_other=other.objects().to_vec(); other.release(&mut second)?; anyhow::ensure!(draw(&mut second,&old_other,camera,&b)?==blank,"Second released placement still draws"); anyhow::ensure!(first.material_texture_stats().color==0 && second.material_texture_stats().color==0,"Placement texture keys leaked");
    let report=serde_json::json!({"scope":"Two caller-selected original sheep placements; not full map rendering, effects, JASS or FPS acceptance","map":map,"worldNodes":world.nodes.len(),"sourceModels":world.models.len(),"selectedNodes":selected,"poseGroups":groups,"objects":object_count,"visiblePixels":changed(&blank,&initial),"animatedPixels":changed(&initial,&animated),"sessionClosedBeforeGpu":true,"mapCacheBytesReleased":before.resident_bytes-after.resident_bytes,"resourceCache":resources.stats(),"parentsPreserved":true,"otherViewUpdatePreserved":true,"bothViewsReleased":true}); std::fs::create_dir_all(&output)?; image::save_buffer(output.join("placements.png"),&initial,size.width,size.height,image::ColorType::Rgba8)?; image::save_buffer(output.join("placements-next.png"),&animated,size.width,size.height,image::ColorType::Rgba8)?; std::fs::write(output.join("receipt.json"),serde_json::to_vec_pretty(&report)?)?; println!("{report}"); Ok(())
}
